import {escapeHTML as e} from './core.js';
export function jellyfinBase(configured,location){if(configured)return configured;return location.hostname.endsWith('.local')?'http://jellyfin.local':`${location.protocol}//${location.hostname}:8096`;}
export function jellyfinItemURL(base,item){const u=new URL(base.replace(/\/$/,'')+'/web/index.html');if(item?.available)u.hash='!/details?'+new URLSearchParams({id:item.itemId,serverId:item.serverId});return u.href;}
export function createIntegrationUI({request,toast,onChange=()=>{}}){
 let config={};
 const local=(path,options={})=>request(path,{...options,server:''});
 async function load(){config=await local('/api/web-settings');return config;}
 const base=()=>jellyfinBase(config.jellyfinUrl,location);
 function html(){return `<div class="settings-layout integration-layout"><section class="settings-group"><h2>TMDB</h2><p class="help" id="tmdb-status">Проверяем подключение…</p><form id="tmdb-form"><label class="field"><span>API Read Access Token</span><input name="tmdbToken" type="password" autocomplete="new-password" placeholder="Новый токен · пустое поле сохраняет текущий" spellcheck="false"></label><div class="form-error" role="alert"></div><div class="integration-actions"><button class="secondary" type="submit">Проверить и сохранить</button><button class="secondary outline" type="button" data-disconnect-tmdb>Отключить</button></div></form><a class="help" href="https://www.themoviedb.org/settings/api" target="_blank" rel="noopener">Получить токен TMDB ↗</a><div class="tmdb-credit"><img src="./tmdb-logo.svg" alt="TMDB" width="100"><p>This product uses the TMDB API but is not endorsed or certified by TMDB.</p></div></section><section class="settings-group"><h2>Telegram-бот</h2><p class="help" id="telegram-status">Проверяем настройки…</p><form id="telegram-form"><label class="field"><span>Токен от @BotFather</span><input name="telegramToken" type="password" autocomplete="new-password" placeholder="Пустое поле сохраняет текущий токен" spellcheck="false"></label><label class="field"><span>ID владельца Telegram</span><input name="telegramOwnerId" inputmode="numeric" autocomplete="off" placeholder="Числовой ID аккаунта"></label><label class="setting-row"><span class="setting-copy">Включить бота</span><span class="toggle"><input name="telegramEnabled" type="checkbox"><span></span></span></label><p class="help">ID можно узнать у @userinfobot. Бот отвечает владельцу и приглашённым участникам.</p><div class="form-error" role="alert"></div><button class="secondary" type="submit">Сохранить настройки бота</button></form></section><section class="settings-group"><h2>Jellyfin</h2><form id="jellyfin-form"><label class="field"><span>Адрес для перехода</span><input name="jellyfinUrl" type="url" placeholder="Автоматически по адресу WatchNext"></label><p class="help">Для VPN можно указать IP и порт. Если адрес пустой, используем jellyfin.local или IP этого сервера. В Jellyfin потребуется обычный вход в ваш профиль.</p><div class="form-error" role="alert"></div><div class="integration-actions"><button class="secondary" type="submit">Сохранить адрес</button><a class="secondary outline" id="open-jellyfin-settings" href="${e(jellyfinItemURL(base()))}" target="_blank" rel="noopener">Открыть Jellyfin ↗</a></div></form></section></div>`;}
 function bind(form,submit){form?.addEventListener('submit',async event=>{event.preventDefault();event.stopPropagation();const button=form.querySelector('button[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';try{await submit(new FormData(form));form.querySelectorAll('input[type=password]').forEach(i=>i.value='');toast('Настройки сохранены');}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});}
 async function mount(){const host=document.querySelector('#integration-settings');if(!host)return;host.innerHTML=html();const tmdbForm=host.querySelector('#tmdb-form'),tgForm=host.querySelector('#telegram-form'),jfForm=host.querySelector('#jellyfin-form');const updateStatus=()=>{host.querySelector('#tmdb-status').textContent=config.tmdbConfigured?'Подключён · токен хранится только на сервере':'TMDB не подключён';};
 bind(tmdbForm,async data=>{config=await local('/api/web-settings',{method:'POST',body:{tmdbToken:String(data.get('tmdbToken'))}});updateStatus();onChange();});
 host.querySelector('[data-disconnect-tmdb]').onclick=async()=>{try{config=await local('/api/web-settings',{method:'POST',body:{removeTmdb:true}});updateStatus();onChange();toast('TMDB отключён');}catch(err){tmdbForm.querySelector('.form-error').textContent=err.message;}};
 const fillTG=data=>{tgForm.elements.telegramOwnerId.value=data.telegramOwnerId||'';tgForm.elements.telegramEnabled.checked=data.telegramEnabled;host.querySelector('#telegram-status').textContent=data.telegramEnabled?'Бот включён'+(data.telegramUsername?' · @'+data.telegramUsername:''):data.telegramConfigured?'Бот настроен и выключен':'Бот не подключён';};
 bind(tgForm,async data=>fillTG(await request('/api/integrations',{method:'POST',body:{telegramToken:String(data.get('telegramToken')),telegramOwnerId:String(data.get('telegramOwnerId')),telegramEnabled:data.get('telegramEnabled')==='on'}})));
 bind(jfForm,async data=>{config=await local('/api/web-settings',{method:'POST',body:{jellyfinUrl:String(data.get('jellyfinUrl'))}});host.querySelector('#open-jellyfin-settings').href=jellyfinItemURL(base());onChange();});
 await Promise.allSettled([load().then(()=>{if(!host.isConnected)return;updateStatus();jfForm.elements.jellyfinUrl.value=config.jellyfinUrl||'';host.querySelector('#open-jellyfin-settings').href=jellyfinItemURL(base());}).catch(err=>host.querySelector('#tmdb-status').textContent=err.message),request('/api/integrations').then(data=>{if(host.isConnected)fillTG(data);}).catch(err=>host.querySelector('#telegram-status').textContent=err.message)]);
 }
 async function open(pack,index){try{const item=await request('/api/jellyfin/link?'+new URLSearchParams({pack,...(index===undefined?{}:{index})}));if(!item.available){toast(item.reason||'Файл ещё недоступен в Jellyfin');return;}location.href=jellyfinItemURL(base(),item);}catch(err){toast(err.message);}}
 return {mount,load,open,home:()=>jellyfinItemURL(base())};
}
